// Reescrito 28-sep: antes armaba el contexto de la IA leyendo métricas de Facebook que ni
// se pedían (reach/impressions/engaged_users → siempre 0), trataba los totales de cuenta de
// Instagram como si fueran una lista de posts, y le decía a la IA "últimos 30 días" en un
// reporte semanal. Ahora usa exactamente los mismos números que se guardan en G54
// (📊 Preparar Métricas G54, que corre antes), así el reporte y el panel dicen lo mismo.
const config = $('⚙️ Config Growth54').item.json;
const empresa = ($('📊 Obtener Perfil Empresa').item?.json || {}).data || {};
const estrategia = ($('🎯 Obtener Estrategia G54').item?.json || {}).data || {};
const posts = ($('📝 Obtener Posts Publicados G54').item?.json || {}).data || [];
const leads = ($('💼 Obtener Leads G54').item?.json || {}).data || [];
const m = $('📊 Preparar Métricas G54').item.json;

const desde = m.period_start, hasta = m.period_end;
const enSemana = f => { const d = (f || '').slice(0, 10); return d && d >= desde && d <= hasta; };

// Posts publicados de la semana, por red (dato de G54)
const postsSemana = posts.filter(p => (p.status || 'publicado') === 'publicado' && enSemana(p.fecha_publicada || p.fecha_programada));
const postsPorPlataforma = postsSemana.reduce((acc, p) => { const pl = p.platform || 'sin_plataforma'; acc[pl] = (acc[pl] || 0) + 1; return acc; }, {});

// Leads de la semana
const leadsSemana = leads.filter(l => enSemana(l.created_at || l.fecha || l.ultima_actividad));
const totalLeads = leadsSemana.length;
const leadsCalientes = leadsSemana.filter(l => (l.clasificacion || '').toLowerCase() === 'caliente').length;
const leadsTibios = leadsSemana.filter(l => (l.clasificacion || '').toLowerCase() === 'tibio').length;
const leadsPorOrigen = leadsSemana.reduce((acc, l) => { const o = l.origen || 'desconocido'; acc[o] = (acc[o] || 0) + 1; return acc; }, {});

const fb = m.fb || {}, ig = m.ig || {};
const kpis = estrategia.kpis || [];
const pilares = estrategia.pilares || [];
const nombreEmpresa = empresa.name || 'la empresa';

const contextoAnalytics = `EMPRESA: ${nombreEmpresa}
OBJETIVO ESTRATÉGICO: ${estrategia.objetivo || ''}
AUDIENCIA: ${estrategia.audiencia || ''}
PILARES DE CONTENIDO: ${Array.isArray(pilares) ? pilares.join(', ') : pilares}
KPIs DEFINIDOS: ${Array.isArray(kpis) ? kpis.join(', ') : kpis}
PERÍODO: semana del ${desde} al ${hasta} (7 días)

--- FACEBOOK (datos reales de Meta, solo posts de esta semana) ---
Posts: ${fb.posts || 0} · Alcance: ${fb.alcance || 0} · Visualizaciones: ${fb.impresiones || 0} · Reacciones: ${fb.reacciones || 0} · Comentarios: ${fb.comentarios || 0} · Compartidos: ${fb.compartidos || 0} · Clics: ${fb.clics || 0}
Visitas a la página: ${fb.visitas_perfil || 0} · Seguidores nuevos: ${fb.seguidores_nuevos || 0}
Detalle por post:
${(fb.detalle || []).length ? JSON.stringify(fb.detalle, null, 2) : 'Sin posts de Facebook en la semana'}

--- INSTAGRAM (datos reales de Meta, totales de la cuenta en la semana) ---
Alcance: ${ig.alcance || 0} · Visualizaciones: ${ig.impresiones || 0} · Interacciones: ${ig.engagement || 0} · Guardados: ${ig.guardados || 0} · Compartidos: ${ig.compartidos || 0} · Visitas al perfil: ${ig.visitas_perfil || 0} · Clics al sitio: ${ig.clics || 0}

--- LINKEDIN ---
Sin métricas: el token actual no tiene permiso de estadísticas (no inventar números de LinkedIn).

--- CONVERSIÓN EN LA SEMANA (G54) ---
Leads: ${totalLeads} · Calientes: ${leadsCalientes} · Tibios: ${leadsTibios}
Por origen: ${JSON.stringify(leadsPorOrigen)}
Tasa de calificación: ${totalLeads > 0 ? Math.round((leadsCalientes / totalLeads) * 100) : 0}%

IMPORTANTE: usa solo estos números. Si un valor es 0 o no hay datos, dilo tal cual — nunca estimes ni inventes métricas.`;

return [{ json: {
  contextoAnalytics,
  nombreEmpresa,
  emailEmpresa: (empresa.emails || [])[0] || '',
  // el endpoint de posts de G54 que usa este workflow no trae los ya publicados — se usa el conteo real de Meta
  totalPosts: fb.posts || 0,
  totalLeads,
  leadsCalientes,
  periodoAnalisis: 7
} }];

const groqRaw = $('🤖 Groq: Analytics AI').item.json;
const texto = groqRaw.choices?.[0]?.message?.content || '';

const get = (label) => {
  const regex = new RegExp(`(?:^|\\n)\\*{0,2}\\s*${label}\\s*\\*{0,2}[:\\s]+([\\s\\S]*?)(?=\\n\\*{0,2}[A-ZÁÉÍÓÚ][A-ZÁÉÍÓÚ\\s]+\\*{0,2}:|$)`, 'i');
  const match = texto.match(regex);
  return (match?.[1] || '').trim();
};

const reporte = get('REPORTE');
const topContenido = get('TOP CONTENIDO');
const bajoRendimiento = get('BAJO RENDIMIENTO');
const insightsSEO = get('INSIGHTS SEO');
const insightsAEO = get('INSIGHTS AEO');
const insightsGEO = get('INSIGHTS GEO');
const insightsConversion = get('INSIGHTS CONVERSI[ÓO]N');
const recomendaciones = get('RECOMENDACIONES');

const datos = $('🔧 Preparar Datos Analytics').item.json;

return [{ json: {
  reporte,
  topContenido,
  bajoRendimiento,
  insightsSEO,
  insightsAEO,
  insightsGEO,
  insightsConversion,
  recomendaciones,
  texto_completo: texto,
  nombreEmpresa: datos.nombreEmpresa,
  emailEmpresa: datos.emailEmpresa,
  totalPosts: datos.totalPosts,
  totalLeads: datos.totalLeads,
  leadsCalientes: datos.leadsCalientes,
  periodoAnalisis: datos.periodoAnalisis
}}];

// Reescrito 28-sep: antes (1) Facebook sumaba los últimos 10 posts sin importar la fecha
// — como G54 ACUMULA una fila por corrida, cada semana volvía a contar posts de semanas
// anteriores; (2) Instagram se calculaba pero el guardado mandaba 0 fijo; (3) impresiones
// era una copia del alcance; (4) guardados/compartidos/visitas/seguidores nunca se mandaban.
// Ahora todo se pide a Meta acotado a la semana real (since/until) y se devuelve por red.
// post_impressions / post_fan_reach ya no sirven: Meta los dio de baja o cuentan solo fans —
// se usan post_total_media_view_unique (alcance) y post_media_view (visualizaciones).
const config = $('⚙️ Config Growth54').item.json;
const PAGE = config.FB_PAGE_ID;
const PT = $('🔑 Obtener Page Token FB').item.json.access_token;
const IGID = $('🔑 Obtener Tokens Sociales G64').item.json.ig_user_id;
const G = 'https://graph.facebook.com/v19.0/';

const now = new Date();
const periodEnd = now.toISOString().slice(0, 10);
const periodStart = new Date(now - 7 * 86400000).toISOString().slice(0, 10);

const get = async (path, params) => {
  const qs = Object.entries({ ...params, access_token: PT })
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
  try { return await this.helpers.httpRequest({ method: 'GET', url: G + path + '?' + qs, json: true, timeout: 30000 }); }
  catch (e) { return null; }
};
const sumObj = v => (v && typeof v === 'object') ? Object.values(v).reduce((a, b) => a + (Number(b) || 0), 0) : (Number(v) || 0);

// ---------- Facebook: posts publicados DENTRO de la semana ----------
const fb = { alcance: 0, impresiones: 0, engagement: 0, clics: 0, reacciones: 0, compartidos: 0, comentarios: 0,
             visitas_perfil: 0, seguidores_nuevos: 0, guardados: 0, posts: 0 };
if (PAGE && PT) {
  const r = await get(PAGE + '/published_posts', {
    since: periodStart, until: periodEnd, limit: 100,
    fields: 'id,created_time,message,permalink_url,shares,insights.metric(post_total_media_view_unique,post_media_view,post_reactions_by_type_total,post_clicks_by_type,post_activity_by_action_type)'
  });
  const posts = (r && r.data) || [];
  fb.posts = posts.length;
  fb.detalle = [];
  for (const p of posts) {
    const ins = (p.insights && p.insights.data) || [];
    const val = name => {
      const vals = ins.filter(i => i.name === name).map(i => (i.values && i.values[0]) ? i.values[0].value : 0);
      return vals.length ? Math.max(...vals.map(sumObj)) : 0;
    };
    const act = (ins.find(i => i.name === 'post_activity_by_action_type') || {}).values;
    const acts = (act && act[0] && act[0].value) || {};
    fb.alcance += val('post_total_media_view_unique');
    fb.impresiones += val('post_media_view');
    fb.reacciones += val('post_reactions_by_type_total');
    fb.clics += val('post_clicks_by_type');
    fb.comentarios += Number(acts.comment) || 0;
    fb.compartidos += (p.shares && p.shares.count) || Number(acts.share) || 0;
    fb.detalle.push({ meta_id: p.id, fecha:(p.created_time || '').slice(0, 10), texto: (p.message || '').split(String.fromCharCode(10))[0].slice(0, 90),
      alcance: val('post_total_media_view_unique'), visualizaciones: val('post_media_view'),
      reacciones: val('post_reactions_by_type_total'), clics: val('post_clicks_by_type'),
      comentarios: Number(acts.comment) || 0, compartidos: (p.shares && p.shares.count) || Number(acts.share) || 0 });
  }
  fb.engagement = fb.reacciones + fb.clics + fb.comentarios + fb.compartidos;
  // Nivel página: visitas y seguidores nuevos de la semana
  const pg = await get(PAGE + '/insights', { metric: 'page_views_total,page_daily_follows_unique', period: 'day', since: periodStart, until: periodEnd });
  for (const m of ((pg && pg.data) || [])) {
    const s = (m.values || []).reduce((a, v) => a + (Number(v.value) || 0), 0);
    if (m.name === 'page_views_total') fb.visitas_perfil = s;
    if (m.name === 'page_daily_follows_unique') fb.seguidores_nuevos = s;
  }
}

// ---------- Instagram: métricas de cuenta de la semana ----------
const ig = { alcance: 0, impresiones: 0, engagement: 0, clics: 0, guardados: 0, compartidos: 0,
             visitas_perfil: 0, seguidores_nuevos: 0, profile_views: 0 };
if (IGID && PT) {
  const r = await get(IGID + '/insights', {
    metric: 'reach,views,total_interactions,saves,shares,profile_views,website_clicks',
    metric_type: 'total_value', period: 'day', since: periodStart, until: periodEnd
  });
  const v = name => { const m = ((r && r.data) || []).find(x => x.name === name); return (m && m.total_value && Number(m.total_value.value)) || 0; };
  ig.alcance = v('reach'); ig.impresiones = v('views'); ig.engagement = v('total_interactions');
  ig.guardados = v('saves'); ig.compartidos = v('shares'); ig.clics = v('website_clicks');
  ig.visitas_perfil = v('profile_views'); ig.profile_views = ig.visitas_perfil;
  // follower_count solo lo da Meta con 100+ seguidores; si no viene, queda 0 (no se inventa).
  const f = await get(IGID + '/insights', { metric: 'follower_count', period: 'day', since: periodStart, until: periodEnd });
  const fc = ((f && f.data) || [])[0];
  if (fc) ig.seguidores_nuevos = (fc.values || []).reduce((a, x) => a + (Number(x.value) || 0), 0);
  // Detalle por post de Instagram de la semana (para las métricas por post / Top Posts)
  ig.detalle = [];
  const media = await get(IGID + '/media', { fields: 'id,timestamp,caption,media_type', since: periodStart, until: periodEnd, limit: 50 });
  for (const md of ((media && media.data) || [])) {
    const mi = await get(md.id + '/insights', { metric: 'reach,views,total_interactions,saved,shares' });
    const mv = name => { const x = ((mi && mi.data) || []).find(y => y.name === name); return (x && x.values && x.values[0] && Number(x.values[0].value)) || 0; };
    ig.detalle.push({ meta_id: md.id, fecha: (md.timestamp || '').slice(0, 10), texto: (md.caption || '').split(String.fromCharCode(10))[0].slice(0, 90),
      alcance: mv('reach'), visualizaciones: mv('views'), interacciones: mv('total_interactions'), guardados: mv('saved'), compartidos: mv('shares') });
  }
}

const rate = (e, a) => a > 0 ? parseFloat((e / a * 100).toFixed(2)) : 0;
return [{ json: {
  period_start: periodStart,
  period_end: periodEnd,
  fb, ig,
  engagement_rate_fb: rate(fb.engagement, fb.alcance),
  engagement_rate_ig: rate(ig.engagement, ig.alcance),
  engagement_rate: rate(fb.engagement, fb.alcance)
} }];

const query = $('🌐 Trigger Webhook').item.json.query || {};
const body  = $('🌐 Trigger Webhook').item.json.body  || {};
const postId    = query.post_id    || body.post_id;
const companyId = query.company_id || body.company_id || $('⚙️ Config Growth54').item.json.G54_COMPANY_ID;

const insData = $('📊 Meta API: Post Insights').item?.json?.data || [];

const getVal = (name) => insData.find(i => i.name === name)?.values?.[0]?.value || 0;
const getObjSum = (name) => {
  const v = insData.find(i => i.name === name)?.values?.[0]?.value;
  if (!v) return 0;
  if (typeof v === 'object') return Object.values(v).reduce((a,b) => a+b, 0);
  return v;
};

const alcance    = getVal('post_fan_reach');
const reacciones = getVal('post_reactions_like_total');
const clics      = getObjSum('post_clicks_by_type');
const engagement = reacciones + clics;
const engRate    = alcance > 0 ? parseFloat((engagement / alcance * 100).toFixed(2)) : 0;
const today      = new Date().toISOString().slice(0,10);

return [{
  json: {
    company_id: parseInt(companyId) || 1,
    post_id: postId,
    platform: String(postId).includes('_') ? 'facebook' : 'instagram',
    period_start: today,
    period_end: today,
    alcance_total: alcance,
    impresiones_total: alcance,
    engagement_total: engagement,
    engagement_rate_avg: engRate,
    clics_total: clics,
    leads_total: 0
  }
}];

